   435→import { useState, useEffect, useMemo, useCallback } from 'react';
   436→import type { Kurse, Teilnehmer, Kursanmeldung, Dozenten, Raeume, Anmeldungen } from '@/types/app';
   437→import { LivingAppsService } from '@/services/livingAppsService';
   438→
   439→export function useDashboardData() {
   440→  const [kurse, setKurse] = useState<Kurse[]>([]);
   441→  const [teilnehmer, setTeilnehmer] = useState<Teilnehmer[]>([]);
   442→  const [kursanmeldung, setKursanmeldung] = useState<Kursanmeldung[]>([]);
   443→  const [dozenten, setDozenten] = useState<Dozenten[]>([]);
   444→  const [raeume, setRaeume] = useState<Raeume[]>([]);
   445→  const [anmeldungen, setAnmeldungen] = useState<Anmeldungen[]>([]);
   446→  const [loading, setLoading] = useState(true);
   447→  const [error, setError] = useState<Error | null>(null);
   448→
   449→  const fetchAll = useCallback(async () => {
   450→    setError(null);
   451→    try {
   452→      const [kurseData, teilnehmerData, kursanmeldungData, dozentenData, raeumeData, anmeldungenData] = await Promise.all([
   453→        LivingAppsService.getKurse(),
   454→        LivingAppsService.getTeilnehmer(),
   455→        LivingAppsService.getKursanmeldung(),
   456→        LivingAppsService.getDozenten(),
   457→        LivingAppsService.getRaeume(),
   458→        LivingAppsService.getAnmeldungen(),
   459→      ]);
   460→      setKurse(kurseData);
   461→      setTeilnehmer(teilnehmerData);
   462→      setKursanmeldung(kursanmeldungData);
   463→      setDozenten(dozentenData);
   464→      setRaeume(raeumeData);
   465→      setAnmeldungen(anmeldungenData);
   466→    } catch (err) {
   467→      setError(err instanceof Error ? err : new Error('Fehler beim Laden der Daten'));
   468→    } finally {
   469→      setLoading(false);
   470→    }
   471→  }, []);
   472→
   473→  useEffect(() => { fetchAll(); }, [fetchAll]);
   474→
   475→  const kurseMap = useMemo(() => {
   476→    const m = new Map<string, Kurse>();
   477→    kurse.forEach(r => m.set(r.record_id, r));
   478→    return m;
   479→  }, [kurse]);
   480→
   481→  const teilnehmerMap = useMemo(() => {
   482→    const m = new Map<string, Teilnehmer>();
   483→    teilnehmer.forEach(r => m.set(r.record_id, r));
   484→    return m;
   485→  }, [teilnehmer]);
   486→
   487→  const dozentenMap = useMemo(() => {
   488→    const m = new Map<string, Dozenten>();
   489→    dozenten.forEach(r => m.set(r.record_id, r));
   490→    return m;
